import { validatePostExtraForm } from '../../../src/utils/postInspectionValidate'

describe('validatePostExtraForm bug7008', () => {
  it('空表单首错为整改措施', () => {
    expect(validatePostExtraForm({})).toBe('请输入整改措施')
