    expect(
      validatePostExtraForm({
        rectifyMeasure: 'm',
        rectifyDeadline: '2026-11-26',
        rectifyState: '待整改',
        rectifyUser: '张三',
        photos: [{ status: 'done', url: 'https://x/1.jpg' }],
      }),
    ).toBeNull()
  })
})

